import { readFileSync, writeFileSync } from "node:fs";
import { format } from "prettier";

const plan = JSON.parse(
  readFileSync("specs/rocky/implementation-plan.json", "utf8"),
);
const counts = Object.fromEntries(
  plan.testStatusLegend.map((status) => [
    status,
    plan.acceptance.filter((a) => a.status === status).length,
  ]),
);
const cell = (value) =>
  String(value).replaceAll("|", "\\|").replaceAll("\n", " ");
const content = await format(
  [
    "# Acceptance status",
    "",
    "<!-- Generated by npm run docs:status from specs/rocky/implementation-plan.json. -->",
    "",
    "This table reflects the [task/acceptance ledger](../../specs/rocky/implementation-plan.json). Each status retains the scope and limitations of its linked evidence. A passed fixture does not establish live or cross-platform acceptance. See [record conventions](README.md) and [current release gaps](../ROADMAP.md).",
    "",
    Object.entries(counts)
      .map(([status, count]) => `**${status}: ${count}**`)
      .join(" · "),
    "",
    "The latest evidence entry is shown for each acceptance item. Commands and exit codes belong to that entry; an aggregation command exiting zero does not override a failed acceptance verdict. The ledger retains earlier evidence.",
    "",
    "| Acceptance | Title | Commit | Platform | Mode | Status | Command | Report | Limitations |",
    "| --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ...plan.acceptance.map((a) => {
      const evidence = a.evidence?.at(-1) ?? {};
      const report = evidence.reportPath?.startsWith("docs/implementation/")
        ? `[report](${evidence.reportPath.slice("docs/implementation/".length)})`
        : cell(evidence.reportPath ?? "Not recorded");
      return `| ${cell(a.id)} | ${cell(a.title)} | ${cell(evidence.commit ?? "Not recorded")} | ${cell(evidence.platform ?? "Not recorded")} | ${cell(evidence.mode ?? "Not recorded")} | ${cell(a.status)} | ${cell(evidence.command ?? "Not recorded")} | ${report} | ${cell((evidence.limitations ?? []).join(" ") || "Not recorded")} |`;
    }),
    "",
  ].join("\n"),
  { parser: "markdown" },
);
const path = "docs/implementation/acceptance-report.md";
if (process.argv.includes("--write")) {
  writeFileSync(path, content);
  console.log(`Updated ${path}`);
} else if (readFileSync(path, "utf8").replaceAll("\r\n", "\n") !== content) {
  throw Error("Acceptance summary is stale. Run npm run docs:status.");
}
